'use strict';
const $=id=>document.getElementById(id);
const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let current=null,chosen=[],summary='';
const codeAlphabet='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const sessionCodes=new Set();
const storageKey='todos-pelo-nicolau:participation:v1';
const packagePrices={1:15,2:25,5:50};
const pixKey='Luizafiorini.ramos@gmail.com';
const receiptPhone='5565993624395';
function isValidCode(code){return typeof code==='string'&&/^[A-HJ-NP-Z2-9]{5}$/.test(code)&&/[A-Z]/.test(code)&&/[2-9]/.test(code)}
function readSavedSelection(){try{const raw=localStorage.getItem(storageKey);if(!raw)return {status:'empty'};const saved=JSON.parse(raw);if(!saved||saved.version!==1||![1,2,5].includes(saved.count)||!Array.isArray(saved.codes)||saved.codes.length!==saved.count||!saved.codes.every(isValidCode)||new Set(saved.codes).size!==saved.count||!Array.isArray(saved.generatedCodes)||!saved.generatedCodes.every(isValidCode))return {status:'invalid'};return {status:'saved',saved}}catch(error){return {status:error instanceof SyntaxError?'invalid':'unavailable'}}}
function saveSelection(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,count:current.count,codes:chosen,generatedCodes:[...sessionCodes]}));$('storage-status').textContent='Códigos salvos neste navegador. Você pode atualizar ou reabrir a página.'}catch{$('storage-status').textContent='Não foi possível salvar neste navegador. Copie seu resumo antes de sair.'}}
function renderSelection(){document.querySelectorAll('.package').forEach(button=>{const active=Number(button.dataset.count)===current.count;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});$('assigned').replaceChildren(...chosen.map(code=>{const s=document.createElement('span');s.textContent=code;return s}));$('number-help').textContent='Guarde também o resumo e confirme sua participação com a organização.';$('shuffle').disabled=false;$('total').textContent=money(current.price);$('summary-count').textContent=current.count===1?'1 código':`${current.count} códigos`;$('form-error').textContent=''}
function restoreSelection(){const result=readSavedSelection();if(result.status==='saved'){result.saved.generatedCodes.forEach(code=>sessionCodes.add(code));result.saved.codes.forEach(code=>sessionCodes.add(code));current={count:result.saved.count,price:packagePrices[result.saved.count]};chosen=result.saved.codes;renderSelection();$('storage-status').textContent='Recuperamos os códigos que você salvou neste navegador.'}else if(result.status==='unavailable'){$('storage-status').textContent='O armazenamento deste navegador está indisponível. Guarde o resumo dos códigos.'}else if(result.status==='invalid'){$('storage-status').textContent='Não foi possível recuperar a seleção anterior. Escolha um pacote para gerar novos códigos.'}}
function randomIndex(max){if(!globalThis.crypto?.getRandomValues)throw new Error('secure-random-unavailable');const value=new Uint32Array(1),limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(value)}while(value[0]>=limit);return value[0]%max}
function createCode(){for(let attempt=0;attempt<1000;attempt++){const code=Array.from({length:5},()=>codeAlphabet[randomIndex(codeAlphabet.length)]).join('');if(/[A-Z]/.test(code)&&/[2-9]/.test(code)&&!sessionCodes.has(code)){sessionCodes.add(code);return code}}throw new Error('code-generation-failed')}
function generate(packageOption=current){if(!packageOption)return;const saved=readSavedSelection();if(saved.status==='saved'){saved.saved.generatedCodes.forEach(code=>sessionCodes.add(code));saved.saved.codes.forEach(code=>sessionCodes.add(code))}let nextCodes;try{nextCodes=Array.from({length:packageOption.count},createCode)}catch{$('form-error').textContent='Não foi possível gerar seus códigos. Tente novamente em um navegador recente.';return}current=packageOption;chosen=nextCodes;renderSelection();saveSelection()}
document.querySelectorAll('.package').forEach(button=>button.addEventListener('click',()=>{const count=Number(button.dataset.count);generate({count,price:packagePrices[count]})}));
$('shuffle').addEventListener('click',()=>generate());
$('phone').addEventListener('input',e=>{const d=e.target.value.replace(/\D/g,'').slice(0,11);let v=d;if(d.length>2)v=`(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length>6){const split=d.length>10?7:6;v=`(${d.slice(0,2)}) ${d.slice(2,split)}-${d.slice(split)}`}e.target.value=v});
$('form').addEventListener('submit',e=>{e.preventDefault();if(!current||chosen.length!==current.count){$('form-error').textContent='Escolha um pacote e gere seus códigos para continuar.';document.querySelector('.package').focus();return}const name=$('name').value.trim(),phone=$('phone').value,digits=phone.replace(/\D/g,'');if(name.length<2){$('form-error').textContent='Informe seu nome para continuar.';$('name').focus();return}if(digits.length<10||digits.length>11){$('form-error').textContent='Informe um WhatsApp com DDD válido.';$('phone').focus();return}$('form-error').textContent='';const rows=[['Nome',name],['WhatsApp',phone],['Pacote',`${current.count} código${current.count===1?'':'s'}`],['Códigos',chosen.join(' · ')],['Contribuição',money(current.price)]];$('preview-content').replaceChildren(...rows.map(([title,value])=>{const p=document.createElement('p'),strong=document.createElement('strong');strong.textContent=title+': ';p.append(strong,document.createTextNode(value));return p}));summary='PARTICIPAÇÃO — Todos pelo Nicolau\n'+rows.map(([k,v])=>`${k}: ${v}`).join('\n')+'\nSorteio: 22 de dezembro de 2026.\nChave Pix: '+pixKey+'\nAguardando conferência do Pix e do comprovante pela organização.';$('send-receipt').href='https://wa.me/'+receiptPhone+'?text='+encodeURIComponent('Olá! Quero confirmar minha participação na rifa.\n\n'+summary+'\n\nVou anexar o comprovante nesta conversa.');$('pix-status').textContent='';$('copy-status').textContent='';$('preview').showModal()});
$('close-dialog').addEventListener('click',()=>$('preview').close());$('preview').addEventListener('click',e=>{if(e.target===$('preview')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
async function copyText(text){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return}const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';const parent=$('preview').open?$('preview'):document.body;parent.append(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw new Error('copy')}
$('copy-pix').addEventListener('click',async()=>{try{await copyText(pixKey);$('pix-status').textContent='Chave Pix copiada. Cole no aplicativo do seu banco.'}catch{$('pix-status').textContent='Não foi possível copiar automaticamente. Selecione a chave acima para copiar.'}});
$('copy').addEventListener('click',async()=>{try{await copyText(summary);$('copy-status').textContent='Resumo copiado com carinho!'}catch{$('copy-status').textContent='Não foi possível copiar automaticamente. Selecione o resumo acima.'}});
$('share').addEventListener('click',async()=>{const data={title:'Todos pelo Nicolau',text:'Um código. Uma chance. Muito amor. Conheça a rifa solidária pelo Nicolau.',url:location.href.split('#')[0]};if(location.protocol==='file:'){$('share-status').textContent='O link de compartilhamento ficará disponível quando o site estiver online.';return}try{if(navigator.share){await navigator.share(data);$('share-status').textContent=''}else{await copyText(data.url);$('share-status').textContent='Link da campanha copiado!'}}catch(e){if(e.name!=='AbortError')$('share-status').textContent='Não foi possível compartilhar. Copie o endereço do navegador.'}});
restoreSelection();
